<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Image to WebP Converter','description'=>'Convert JPG and PNG images to WebP in your browser.','url'=>'https://smarttoolz.in/tools/image-to-webp/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Image to WebP</h1><p>Convert an image to WebP locally.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="f" type="file" accept="image/*"><label>Quality<input id="q" type="range" min="0.1" max="1" step="0.1" value="0.85"></label><button id="go" class="tool-btn">Convert</button><a id="d" class="tool-btn" hidden download="converted.webp">Download WebP</a><p id="o"></p></div></section></main><script>go.onclick=()=>{let f=document.getElementById('f').files[0];if(!f){o.textContent='Choose an image.';return}let i=new Image,u=URL.createObjectURL(f);i.onload=()=>{let c=document.createElement('canvas');c.width=i.width;c.height=i.height;c.getContext('2d').drawImage(i,0,0);c.toBlob(b=>{d.href=URL.createObjectURL(b);d.hidden=false;o.textContent='Conversion complete.'},'image/webp',+q.value)};i.src=u}</script><?php smarttoolz_tool_page_end(); ?>